-- 仅供 MFA 集成测试：每个用例一个独立身份，Authenticator 状态互不影响；均为演示租户成员，密码与演示身份相同。插入须可重复执行。
-- mfa-login 另属第二租户，用于验证 switch 沿用授权上的 MFA 记录。
INSERT INTO tenant (id, name) VALUES ('019a0110-0000-7000-8000-000000000004', '第二租户') ON CONFLICT DO NOTHING;
INSERT INTO identity (id, account, email, display_name, password_hash)
SELECT v.id::uuid, v.account, v.account || '@example.com', v.account, i.password_hash
FROM identity i CROSS JOIN (VALUES
    ('019a0110-0000-7000-8000-000000000301', 'mfa-bind'),
    ('019a0110-0000-7000-8000-000000000302', 'mfa-session'),
    ('019a0110-0000-7000-8000-000000000303', 'mfa-replay'),
    ('019a0110-0000-7000-8000-000000000304', 'mfa-regenerate'),
    ('019a0110-0000-7000-8000-000000000305', 'mfa-unbind'),
    ('019a0110-0000-7000-8000-000000000306', 'mfa-guard'),
    ('019a0110-0000-7000-8000-000000000307', 'mfa-concurrent'),
    ('019a0110-0000-7000-8000-000000000308', 'mfa-login'),
    ('019a0110-0000-7000-8000-000000000309', 'mfa-code-login'),
    ('019a0110-0000-7000-8000-00000000030a', 'mfa-recovery'),
    ('019a0110-0000-7000-8000-00000000030b', 'mfa-expired'),
    ('019a0110-0000-7000-8000-00000000030c', 'mfa-pending'),
    ('019a0110-0000-7000-8000-00000000030d', 'mfa-unbound')) AS v (id, account)
WHERE i.account = 'demo'
ON CONFLICT DO NOTHING;
